useEffect(() => {
  const wasOpen = wasOpenRef.current;
  wasOpenRef.current = isOpen;
  if (isOpen) { setIsClosing(false); return; }
  if (!wasOpen) return;
  setIsClosing(true);
  const durationMs = (parseFloat(getComputedStyle(panelRef.current).animationDuration) || 0) * 1000;
  const t = setTimeout(() => setIsClosing(false), durationMs + 50);
  return () => clearTimeout(t);
}, [isOpen]);
// reduced-motion → duration ~0 → unmount ~50ms; normal → animationend wins
